import 'package:flutter/material.dart';import '../../core/app_state.dart';import '../../core/models.dart';import '../../widgets/common.dart';
class ListsPage extends StatefulWidget{const ListsPage({super.key});@override State<ListsPage> createState()=>_ListsPageState();}
class _ListsPageState extends State<ListsPage> with SingleTickerProviderStateMixin{late final TabController c=TabController(length:3,vsync:this);@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('リスト',style:TextStyle(fontWeight:FontWeight.w800)),bottom:TabBar(controller:c,tabs:const [Tab(text:'やること'),Tab(text:'買いたい'),Tab(text:'予定候補')])),body:PageWrap(child:TabBarView(controller:c,children:const [_Tasks(),_Wants(),_Futures()]));}}
class _Tasks extends StatelessWidget{const _Tasks();@override Widget build(BuildContext context){final s=AppStateScope.of(context);return ListView(padding:const EdgeInsets.fromLTRB(16,12,16,100),children:[for(final b in TaskBucket.values)...[SectionTitle(_bucket(b)),...s.tasks.where((t)=>t.bucket==b&&!t.completed).map((t)=>Card(child:CheckboxListTile(value:t.completed,onChanged:(_)=>s.toggleTask(t),title:Text(t.title),subtitle:t.deadline==null?null:Text('期限 ${t.deadline}'),controlAffinity:ListTileControlAffinity.leading)))],const SectionTitle('完了'),...s.tasks.where((t)=>t.completed).map((t)=>ListTile(leading:const Icon(Icons.check_circle_outline),title:Text(t.title,style:const TextStyle(decoration:TextDecoration.lineThrough))))]);}String _bucket(TaskBucket b)=>switch(b){TaskBucket.inbox=>'Inbox',TaskBucket.today=>'今日',TaskBucket.soon=>'近いうち',TaskBucket.someday=>'いつか'};}
class _Wants extends StatelessWidget{const _Wants();@override Widget build(BuildContext context){final s=AppStateScope.of(context);return ListView(padding:const EdgeInsets.fromLTRB(16,12,16,100),children:[for(final w in s.wants)Card(child:ListTile(leading:const Icon(Icons.shopping_bag_outlined),title:Text(w.title),subtitle:Text([if(w.budget!=null)'予算 ¥${w.budget!.round()}',if(w.waitingFor.isNotEmpty)w.waitingFor].join('  ·  ')),trailing:Text(_status(w.status))))]);}String _status(WantStatus x)=>switch(x){WantStatus.interested=>'気になる',WantStatus.considering=>'検討中',WantStatus.planned=>'買う予定',WantStatus.purchased=>'購入済',WantStatus.dropped=>'見送り'};}
class _Futures extends StatelessWidget{const _Futures();@override Widget build(BuildContext context){final s=AppStateScope.of(context);return ListView(padding:const EdgeInsets.fromLTRB(16,12,16,100),children:[for(final f in s.futures)Card(child:ListTile(leading:const Icon(Icons.push_pin_outlined),title:Text(f.title),subtitle:Text(_status(f.status)),trailing:Text(f.timing)))]);}String _status(FutureStatus x)=>switch(x){FutureStatus.considering=>'考え中',FutureStatus.planned=>'やる予定',FutureStatus.scheduled=>'日程確定',FutureStatus.completed=>'完了',FutureStatus.dropped=>'見送り'};}
